        target = _canonicalize_symbols(target)

    return _expr_eq(
        gold, target, float_rounding, numeric_precision, allow_set_relation_comp, strict
    )


def _expr_eq(
    gold: Any,
    target: Any,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool,
    strict: bool,
) -> bool:
    def compare(a: Any, b: Any) -> bool:
        return _expr_eq(
            a,
            b,
            float_rounding,
            numeric_precision,
            allow_set_relation_comp,
            strict,
        )

