        return False

    # 1. Structural equality, by far the most common case.
    try:
        if gold == target:
            return True
    except Exception:
        pass

    if isinstance(gold, BooleanAtom) or isinstance(target, BooleanAtom):
        return False

    gold_is_relation = _is_relation(gold)
    target_is_relation = _is_relation(target)

    # 2. Relations on both sides.
    if gold_is_relation and target_is_relation:
        if isinstance(gold, Relational) and isinstance(target, Relational):
            if sympy_compare_relational(gold, target, compare):
                return True
