    if gold_is_relation != target_is_relation:
        relation, other = (
            (gold, target) if gold_is_relation else (target, gold)
        )
        if isinstance(other, Set):
            # A compound relation describes a range, so it may always be
            # compared with a set; a simple relation only on request.
            if isinstance(relation, Relational) and not allow_set_relation_comp:
                return False
            relation_set = _relation_to_set(relation)
            if relation_set is not None:
                return sympy_compare_sets(relation_set, other, compare)
            return False
        # ``1/2 $ = 10/9`` - a numeric equation states its answer on one side.
        if isinstance(relation, Eq) and not relation.free_symbols:
            return compare(relation.rhs, other) or compare(relation.lhs, other)
        return False

    # 4. Sets.
    if isinstance(gold, Set) or isinstance(target, Set):
        if isinstance(gold, Set) and isinstance(target, Set):
            if sympy_compare_sets(gold, target, compare):
                return True
