        sequence_result = sympy_deep_compare_set_and_tuple(
            gold, target, compare, strict
        )
        return bool(sequence_result)

    # 5. Tuples and matrices.
    sequence_result = sympy_deep_compare_set_and_tuple(gold, target, compare, strict)
    if sequence_result is not None:
        return sequence_result

    # 6. Plain expressions.
    if sympy_numeric_eq(gold, target, float_rounding, numeric_precision):
        return True
    if sympy_symbolic_eq(gold, target):
        return True
    return False


def verify(
    gold: list[Basic | MatrixBase | str] | Basic | MatrixBase | str,
    target: list[Basic | MatrixBase | str] | Basic | MatrixBase | str,
    float_rounding: int = 6,
    numeric_precision: int = 15,
    strict: bool = True,
    allow_set_relation_comp: bool = False,
    timeout_seconds: int | None = 5,
) -> bool:
    """Verifies that the target answer is equivalent to the gold answer.

    Note that the comparison is not symmetric: ``gold`` is the reference answer
    and ``target`` the answer which is being verified.

    Args:
        gold: The reference answer, as returned by :func:`math_verify.parse`.
        target: The answer to verify.
        float_rounding: Number of decimal places floats are compared with.
        numeric_precision: Significant digits used for numeric evaluation.
        strict: In strict mode variable names matter and sets do not compare
            equal to tuples.
        allow_set_relation_comp: Whether a set may be compared with a simple
            relation (``[1, inf)`` vs ``x >= 1``).
        timeout_seconds: Seconds before a single comparison is aborted. ``None``
            disables the timeout, which is required in multi-threaded code.

    Returns:
        True if any of the gold answers matches any of the target answers.

    Examples:
        >>> from math_verify import parse
        >>> verify(parse("$\\\\frac{1}{2}$"), parse("$0.5$"))
        True
    """

    def compare_single_extraction(gold: Any, target: Any) -> bool:
        if isinstance(gold, (Basic, MatrixBase)) and isinstance(
            target, (Basic, MatrixBase)
        ):
            return sympy_expr_eq(
                gold,
                target,
                float_rounding,
                numeric_precision,
                allow_set_relation_comp,
                strict,
            )
