        # letters, plain words, ...).
        if isinstance(gold, str) and isinstance(target, str):
            gold, target = gold.strip(), target.strip()
            return len(gold) > 0 and gold == target
        return False

    def compare_single_extraction_wrapper(gold: Any, target: Any) -> bool:
        try:
            return timeout(timeout_seconds=timeout_seconds)(compare_single_extraction)(
                gold, target
            )
        except Exception:
            return False

    if not isinstance(gold, list):
        gold = [gold]
    if not isinstance(target, list):
        target = [target]

    return any(
        compare_single_extraction_wrapper(gold_item, target_item)
        for gold_item, target_item in product(gold, target)
    )


