        ) and round(a_value.imag, float_rounding) == round(
            b_value.imag, float_rounding
        )

    # Exact numbers: sqrt(2)*sqrt(2) == 2, pi == pi ...
    try:
        difference = (a - b).evalf(numeric_precision)
        if difference == 0:
            return True
        if _is_number(difference):
            return abs(complex(difference)) < 10 ** (-max(numeric_precision - 2, 1))
    except (TypeError, ValueError):
        return False
    except Exception:
        return False
    return False


def sympy_symbolic_eq(a: Basic | MatrixBase, b: Basic | MatrixBase) -> bool:
    """Compares two expressions by simplifying their difference."""
    try:
        if simplify(a - b) == 0:
            return True
    except (TimeoutException, KeyboardInterrupt):
        raise
    except Exception:
        pass

    try:
        if a.equals(b) is True:
            return True
    except (TimeoutException, KeyboardInterrupt):
        raise
    except Exception:
        pass
    return False


def sympy_str_eq(a: Basic | MatrixBase, b: Basic | MatrixBase) -> bool:
    """Compares the string representation of two expressions."""
    try:
        if str(a) == str(b):
            return True
        if str(safe_sympy_doit(a)) == str(safe_sympy_doit(b)):
            return True
    except Exception:
        pass
    return False


# --------------------------------------------------------------------------- #
# Structure aware comparison
# --------------------------------------------------------------------------- #


def sympy_compare_interval(gold: Interval, target: Interval, compare) -> bool:
    """Compares interval bounds and whether they are open."""
    return (
        bool(gold.left_open) == bool(target.left_open)
        and bool(gold.right_open) == bool(target.right_open)
        and compare(gold.start, target.start)
        and compare(gold.end, target.end)
    )


def sympy_compare_sets(gold: Set, target: Set, compare) -> bool:
    """Compares two sets (finite sets, intervals and their combinations)."""
    if gold == target:
        return True

    if isinstance(gold, Interval) and isinstance(target, Interval):
        return sympy_compare_interval(gold, target, compare)

    if isinstance(gold, FiniteSet) and isinstance(target, FiniteSet):
        return _match_unordered(list(gold.args), list(target.args), compare)

    if type(gold) is type(target) and isinstance(
        gold, (Union, Intersection, Complement)
    ):
        return _match_unordered(list(gold.args), list(target.args), compare)

    # Fall back to exact set arithmetic (handles e.g. Reals \ {0}).
    try:
        if gold.symmetric_difference(target).is_empty is True:
            return True
    except Exception:
        pass
    return False


def sympy_compare_relational(gold: Relational, target: Relational, compare) -> bool:
    """Compares two relations, allowing them to be scaled and/or flipped."""
    gold_expr, gold_kind = _relation_parts(gold)
    target_expr, target_kind = _relation_parts(target)
    if gold_kind is None or target_kind is None:
        return False

    if gold_kind == target_kind and compare(gold_expr, target_expr):
        return True

    # ``2x < 4`` and ``x < 2``, ``x >= 5`` and ``5 <= x``.
    ratio = _constant_ratio(gold_expr, target_expr)
    if ratio is None:
        return False
    if gold_kind in (_EQ, _NE):
        return target_kind == gold_kind
    if ratio.is_positive:
        return gold_kind == target_kind
    if ratio.is_negative:
        return gold_kind == _FLIPPED[target_kind]
    return False


def sympy_deep_compare_set_and_tuple(
    gold: Basic | MatrixBase, target: Basic | MatrixBase, compare, strict: bool
) -> bool | None:
    """Element-wise comparison of tuples, matrices and finite sets.

    Returns None when the pair is not a sequence-like pair.
    """
    gold_items = _elements(gold)
    target_items = _elements(target)
    if gold_items is None or target_items is None:
        return None

    gold_is_set = isinstance(gold, FiniteSet)
    target_is_set = isinstance(target, FiniteSet)

    # In strict mode a set never equals a tuple: {1,2} != (1,2).
    if strict and gold_is_set != target_is_set:
        return False

    if isinstance(gold, MatrixBase) and isinstance(target, MatrixBase):
        if gold.shape != target.shape and not (
            min(gold.shape) == 1 and min(target.shape) == 1
        ):
            return False

    if gold_is_set or target_is_set:
        return _match_unordered(gold_items, target_items, compare)

    if len(gold_items) != len(target_items):
        return False
    return all(compare(g, t) for g, t in zip(gold_items, target_items))


# --------------------------------------------------------------------------- #
# Entry points
# --------------------------------------------------------------------------- #


def sympy_expr_eq(
    gold: Basic | MatrixBase,
    target: Basic | MatrixBase,
    float_rounding: int = 6,
    numeric_precision: int = 15,
    allow_set_relation_comp: bool = False,
    strict: bool = True,
) -> bool:
    """Whether two SymPy expressions are mathematically equivalent.

    Args:
        gold: The reference answer.
        target: The answer to verify.
        float_rounding: Number of decimal places floats are compared with.
        numeric_precision: Significant digits used for numeric evaluation.
        allow_set_relation_comp: Whether a set may be compared with a simple
            relation (``[1, inf)`` vs ``x >= 1``).
        strict: In strict mode variable names matter and sets do not compare
            equal to tuples.

    Returns:
        True if the expressions are equivalent.
    """
    if not strict:
        gold = _canonicalize_symbols(gold)
        target = _canonicalize_symbols(target)

    return _expr_eq(
        gold, target, float_rounding, numeric_precision, allow_set_relation_comp, strict
    )


def _expr_eq(
    gold: Any,
    target: Any,
    float_rounding: int,
    numeric_precision: int,
    allow_set_relation_comp: bool,
    strict: bool,
) -> bool:
    def compare(a: Any, b: Any) -> bool:
        return _expr_eq(
            a,
            b,
            float_rounding,
            numeric_precision,
            allow_set_relation_comp,
            strict,
        )

    if gold is None or target is None:
        return False

    # 1. Structural equality, by far the most common case.
    try:
        if gold == target:
            return True
    except Exception:
        pass

    if isinstance(gold, BooleanAtom) or isinstance(target, BooleanAtom):
        return False

    gold_is_relation = _is_relation(gold)
    target_is_relation = _is_relation(target)

    # 2. Relations on both sides.
    if gold_is_relation and target_is_relation:
        if isinstance(gold, Relational) and isinstance(target, Relational):
            if sympy_compare_relational(gold, target, compare):
                return True
        gold_set = _relation_to_set(gold)
        target_set = _relation_to_set(target)
        if gold_set is not None and target_set is not None:
            return sympy_compare_sets(gold_set, target_set, compare)
        return False

    # 3. A relation against something else.
    if gold_is_relation != target_is_relation:
        relation, other = (
            (gold, target) if gold_is_relation else (target, gold)
        )
        if isinstance(other, Set):
            # A compound relation describes a range, so it may always be
            # compared with a set; a simple relation only on request.
            if isinstance(relation, Relational) and not allow_set_relation_comp:
                return False
            relation_set = _relation_to_set(relation)
            if relation_set is not None:
                return sympy_compare_sets(relation_set, other, compare)
            return False
        # ``1/2 $ = 10/9`` - a numeric equation states its answer on one side.
        if isinstance(relation, Eq) and not relation.free_symbols:
            return compare(relation.rhs, other) or compare(relation.lhs, other)
        return False

    # 4. Sets.
    if isinstance(gold, Set) or isinstance(target, Set):
        if isinstance(gold, Set) and isinstance(target, Set):
            if sympy_compare_sets(gold, target, compare):
                return True
        # A finite set may be compared element-wise with a tuple/matrix.
        sequence_result = sympy_deep_compare_set_and_tuple(
            gold, target, compare, strict
        )
        return bool(sequence_result)

    # 5. Tuples and matrices.
    sequence_result = sympy_deep_compare_set_and_tuple(gold, target, compare, strict)
    if sequence_result is not None:
        return sequence_result

    # 6. Plain expressions.
    if sympy_numeric_eq(gold, target, float_rounding, numeric_precision):
        return True
    if sympy_symbolic_eq(gold, target):
        return True
    return False


def verify(
    gold: list[Basic | MatrixBase | str] | Basic | MatrixBase | str,
    target: list[Basic | MatrixBase | str] | Basic | MatrixBase | str,
    float_rounding: int = 6,
    numeric_precision: int = 15,
    strict: bool = True,
    allow_set_relation_comp: bool = False,
    timeout_seconds: int | None = 5,
) -> bool:
    """Verifies that the target answer is equivalent to the gold answer.

    Note that the comparison is not symmetric: ``gold`` is the reference answer
    and ``target`` the answer which is being verified.

    Args:
        gold: The reference answer, as returned by :func:`math_verify.parse`.
        target: The answer to verify.
        float_rounding: Number of decimal places floats are compared with.
        numeric_precision: Significant digits used for numeric evaluation.
        strict: In strict mode variable names matter and sets do not compare
            equal to tuples.
        allow_set_relation_comp: Whether a set may be compared with a simple
            relation (``[1, inf)`` vs ``x >= 1``).
        timeout_seconds: Seconds before a single comparison is aborted. ``None``
            disables the timeout, which is required in multi-threaded code.

    Returns:
        True if any of the gold answers matches any of the target answers.

    Examples:
        >>> from math_verify import parse
        >>> verify(parse("$\\\\frac{1}{2}$"), parse("$0.5$"))
        True
    """

    def compare_single_extraction(gold: Any, target: Any) -> bool:
        if isinstance(gold, (Basic, MatrixBase)) and isinstance(
            target, (Basic, MatrixBase)
        ):
            return sympy_expr_eq(
                gold,
                target,
                float_rounding,
                numeric_precision,
                allow_set_relation_comp,
                strict,
            )
        # Fallback for answers which could not be parsed (multiple choice
        # letters, plain words, ...).
        if isinstance(gold, str) and isinstance(target, str):
            gold, target = gold.strip(), target.strip()
            return len(gold) > 0 and gold == target
        return False

    def compare_single_extraction_wrapper(gold: Any, target: Any) -> bool:
        try:
            return timeout(timeout_seconds=timeout_seconds)(compare_single_extraction)(
                gold, target
            )
        except Exception:
            return False

    if not isinstance(gold, list):
        gold = [gold]
    if not isinstance(target, list):
        target = [target]

    return any(
        compare_single_extraction_wrapper(gold_item, target_item)
        for gold_item, target_item in product(gold, target)
    )


__all__ = [
    "safe_sympy_doit",
    "sympy_compare_relational",
    "sympy_compare_sets",
    "sympy_deep_compare_set_and_tuple",
    "sympy_expr_eq",
    "sympy_numeric_eq",
    "sympy_str_eq",
    "sympy_symbolic_eq",
    "verify",
]

