"""Evaluation task definitions.

These helpers wire the Math-Verify metric into `lighteval
<https://github.com/huggingface/lighteval>`_. lighteval is an optional
dependency (``pip install math-verify[inference]``), so it is imported lazily:
importing this module never fails, only calling the builders does.
"""

from __future__ import annotations

from typing import Any, Sequence

from math_verify.few_shots import MATH_INSTRUCTION, format_few_shots
from math_verify.metric import math_metric
from math_verify.parser import (
    ExprExtractionConfig,
    ExtractionTarget,
    LatexExtractionConfig,
)

# Datasets we ship a ready made configuration for.
SUPPORTED_TASKS: dict[str, dict[str, Any]] = {
    "math": {
        "dataset": "HuggingFaceH4/MATH-500",
        "gold_column": "solution",
        "query_column": "problem",
    },
    "gsm8k": {
        "dataset": "openai/gsm8k",
        "gold_column": "answer",
        "query_column": "question",
    },
    "aime24": {
        "dataset": "HuggingFaceH4/aime_2024",
        "gold_column": "answer",
        "query_column": "problem",
    },
}


def _require_lighteval() -> Any:
    try:
        import lighteval  # noqa: F401
    except ImportError as exc:  # pragma: no cover - optional dependency
        raise ImportError(
            "lighteval is required for the evaluation tasks, install it with "
            "`pip install math-verify[inference]`."
        ) from exc
    return lighteval


def math_prompt_function(instruction: str = MATH_INSTRUCTION) -> Any:
    """Returns a lighteval prompt function asking for a boxed answer."""
    _require_lighteval()
    from lighteval.tasks.requests import Doc  # type: ignore[import-not-found]

    def prompt_fn(line: dict[str, Any], task_name: str | None = None) -> Any:
        return Doc(
            task_name=task_name or "",
            query=f"{instruction}\n\nProblem:\n{line['problem']}\n\nSolution:\n",
            choices=[line["solution"]],
            gold_index=0,
        )

    return prompt_fn


def math_verify_metric(
    gold_extraction_target: Sequence[ExtractionTarget] = (LatexExtractionConfig(),),
    pred_extraction_target: Sequence[ExtractionTarget] = (
        ExprExtractionConfig(),
        LatexExtractionConfig(),
    ),
    precision: int = 6,
) -> Any:
    """Wraps :func:`math_metric` into a lighteval ``SampleLevelMetric``."""
    _require_lighteval()
    import numpy as np
    from lighteval.metrics.metrics import (  # type: ignore[import-not-found]
        SampleLevelMetric,
    )
    from lighteval.metrics.utils.metric_utils import (  # type: ignore[import-not-found]
        MetricCategory,
        MetricUseCase,
    )

    return SampleLevelMetric(
        metric_name="math_verify",
        sample_level_fn=math_metric(
            gold_extraction_target=gold_extraction_target,
            pred_extraction_target=pred_extraction_target,
            precision=precision,
        ),
        category=MetricCategory.GENERATIVE,
        use_case=MetricUseCase.MATH,
        corpus_level_fn=np.mean,
        higher_is_better=True,
    )


def get_task_config(task: str) -> dict[str, Any]:
    """Returns the dataset configuration of one of the :data:`SUPPORTED_TASKS`."""
    if task not in SUPPORTED_TASKS:
        raise ValueError(
            f"Unknown task {task!r}, expected one of {sorted(SUPPORTED_TASKS)}."
        )
    return dict(SUPPORTED_TASKS[task])


__all__ = [
    "SUPPORTED_TASKS",
    "format_few_shots",
    "get_task_config",
    "math_prompt_function",
    "math_verify_metric",
]

